<?php declare(strict_types=1); namespace Annam; $title=$label;$subtitle=$total.' '.($total===1?'order':'orders').' · Orders, payments and bills for this source.';$actions=$channel!=='web'?'<a class="o-btn o-btn-primary" href="/billing/new/?channel='.e($channel).'">＋ Enter booking</a>':''; ?>
<form method="get" class="o-card b-filter"><label class="b-search"><span class="b-label">Find an order</span><input class="o-input" name="q" value="<?= e($query) ?>" placeholder="Search by order number, name or phone"></label><label><span class="b-label">Payment status</span><select class="o-input" name="status"><?php foreach([''=>'All payment statuses','paid'=>'Paid','unpaid'=>'Not paid'] as $key=>$text): ?><option value="<?= e($key) ?>" <?= $status===$key?'selected':'' ?>><?= e($text) ?></option><?php endforeach; ?></select></label><button class="o-btn">Apply filters</button></form>
<section class="o-card"><ul class="o-rows o-rows-static"><?php foreach($records as $r): ?><li><span><a href="/billing/orders/<?= e($r['id']) ?>/"><b><?= e($r['order_no']) ?></b></a><small><?= e($r['address']['recipient_name']??$r['customer_name']) ?> · <?= e($r['address']['phone']??$r['customer_phone']) ?></small></span><span><?= e(ucfirst(str_replace('_',' ',$r['status']))) ?><small><?= e(BillingPortal::paymentLabel($r['payment_status'])) ?></small></span><span><?= money($r['total']) ?><?php if($r['invoice']): ?><br><a href="/billing/bills/<?= e($r['invoice']['id']) ?>/"><?= e($r['invoice']['number']) ?></a><?php endif; ?></span></li><?php endforeach; ?><?php if(!$records): ?><li class="b-empty"><h2><?= $query||$status?'No matching orders':'Your first order starts here' ?></h2><p>Keep bookings, payment confirmations and bills together in one place.</p><?php if($channel!=='web'): ?><a class="o-btn o-btn-primary" href="/billing/new/?channel=<?= e($channel) ?>">Enter a booking</a><?php endif; ?></li><?php endif; ?></ul></section><?php if($pages>1): ?><p><?php if($page>1): ?><a href="?<?= e(http_build_query(['page'=>$page-1,'q'=>$query,'status'=>$status])) ?>">Previous</a><?php endif; ?> Page <?= e($page) ?> of <?= e($pages) ?> <?php if($page<$pages): ?><a href="?<?= e(http_build_query(['page'=>$page+1,'q'=>$query,'status'=>$status])) ?>">Next</a><?php endif; ?></p><?php endif; ?>
